import React from 'react';
import {
    AppBar,
    Toolbar,
    Typography,
    Box,
    IconButton,
    Chip,
    Tooltip,
    Avatar,
} from '@mui/material';
import RefreshIcon from '@mui/icons-material/Refresh';
import NotificationsIcon from '@mui/icons-material/Notifications';
import SettingsIcon from '@mui/icons-material/Settings';
import logo from '../../assets/Eskom-logo-white.gif';

interface HeaderProps {
    lastUpdated?: string;
    onRefresh?: () => void;
    loading?: boolean;
}

const Header: React.FC<HeaderProps> = ({ lastUpdated, onRefresh, loading = false }) => {
    return (
        <AppBar
            position="static"
            elevation={0}
            sx={{
                backgroundColor: '#0D63F4',
                backgroundImage: 'linear-gradient(135deg, #0D63F4 0%, #0849B7 100%)',
                borderBottom: '1px solid rgba(255, 255, 255, 0.1)',
            }}
        >
            <Toolbar sx={{ py: 1 }}>
                <Box display="flex" alignItems="center" flex={1}>
                    <img
                        src={logo}
                        alt="Eskom Logo"
                        style={{ height: 48, marginRight: 16 }}
                    />
                    <Box>
                        <Typography variant="h5" fontWeight={800} color="white">
                            Coal Stockpile Forecasting
                        </Typography>
                        <Typography variant="body2" sx={{ color: 'rgba(255, 255, 255, 0.8)', mt: 0.5 }}>
                            Real-time Analytics & Predictions
                        </Typography>
                    </Box>
                </Box>

                <Box display="flex" alignItems="center" gap={2}>
                    {lastUpdated && (
                        <Chip
                            label={`Updated: ${lastUpdated}`}
                            size="small"
                            sx={{
                                backgroundColor: 'rgba(255, 255, 255, 0.15)',
                                color: 'white',
                                fontWeight: 600,
                                backdropFilter: 'blur(10px)',
                            }}
                        />
                    )}

                    <Tooltip title="Refresh Data">
                        <IconButton
                            color="inherit"
                            onClick={onRefresh}
                            disabled={loading}
                            sx={{
                                backgroundColor: 'rgba(255, 255, 255, 0.1)',
                                '&:hover': {
                                    backgroundColor: 'rgba(255, 255, 255, 0.2)',
                                },
                            }}
                        >
                            <RefreshIcon sx={{ animation: loading ? 'spin 1s linear infinite' : 'none' }} />
                        </IconButton>
                    </Tooltip>

                    <Tooltip title="Notifications">
                        <IconButton
                            color="inherit"
                            sx={{
                                backgroundColor: 'rgba(255, 255, 255, 0.1)',
                                '&:hover': {
                                    backgroundColor: 'rgba(255, 255, 255, 0.2)',
                                },
                            }}
                        >
                            <NotificationsIcon />
                        </IconButton>
                    </Tooltip>

                    <Tooltip title="Settings">
                        <IconButton
                            color="inherit"
                            sx={{
                                backgroundColor: 'rgba(255, 255, 255, 0.1)',
                                '&:hover': {
                                    backgroundColor: 'rgba(255, 255, 255, 0.2)',
                                },
                            }}
                        >
                            <SettingsIcon />
                        </IconButton>
                    </Tooltip>

                    <Avatar
                        sx={{
                            bgcolor: 'rgba(255, 255, 255, 0.2)',
                            fontWeight: 700,
                            ml: 1,
                        }}
                    >
                        U
                    </Avatar>
                </Box>
            </Toolbar>

            <style>
                {`
          @keyframes spin {
            from {
              transform: rotate(0deg);
            }
            to {
              transform: rotate(360deg);
            }
          }
        `}
            </style>
        </AppBar>
    );
};

export default Header;
